"""
The place angle logic (src/full_check.choose_place_window, M183 and M184), with the working / failing turns written into the test. No simulation for cases 1 to 6 (pure arithmetic);
case 7 loads the scene only to build the stance selection's context (no full check, no episode).

    MUJOCO_GL=egl python experiments/place_theta_logic_test.py

Rules under test (stated in choose_place_window's docstring), turns every 5 degrees, a window needs 10 degrees:
  * the widest window wins; * the circle is closed (345, 350, 355, 0, 5 is one window); * the chosen angle is the middle turn of the window; with an even number of turns (the middle falls
    between two steps) the LATER of the two middle turns; * equally wide windows: the one first going up from 0 degrees, a window across 0 counting as the one at 0;
  * a window under 10 degrees fails; * navigation off: the angle is computed at the current stance (the search is called with TASK_CFG's stance) and is not 0.
"""

import copy
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))

from src.full_check import choose_place_window  # noqa: E402

results = []


def check(name, ok, detail=""):
    results.append(bool(ok))
    print(f"  {'PASS' if ok else 'FAIL'}  {name}  {detail}", flush=True)


STEP, NEED = 5, 10
rng = lambda a, b: list(range(a, b + 1, STEP))        # a, a+5, ..., b


def pick(passing):
    return choose_place_window(passing, STEP, NEED)


def case_widest():
    print("\n1. the widest window is chosen")
    r = pick(rng(20, 40) + rng(100, 150) + rng(200, 210))        # 5, 11 and 3 turns
    check("windows 20-40, 100-150, 200-210: the 100-150 one (width 50), middle 125", r["theta_deg"] == 125 and r["window_deg"] == [100, 150] and r["width_deg"] == 50, f"{r['theta_deg']} {r['window_deg']}")


def case_wrap():
    print("\n2. a window across 0 degrees is one window")
    r = pick([345, 350, 355, 0, 5])
    check("345, 350, 355, 0, 5: one window [-15, 5], width 20, middle -5 (355)", r["windows"] == [[-15, 5]] and r["width_deg"] == 20 and r["theta_deg"] == -5, f"{r['windows']} {r['width_deg']} {r['theta_deg']}")
    r2 = pick([0, 5] + rng(350, 355) + rng(100, 110))
    check("0, 5 with 350, 355 beside 100-110 (3 turns): the wrapped window (4 turns) is wider and wins, middle: later of the two middle turns = 0", r2["window_deg"] == [-10, 5] and r2["theta_deg"] == 0, f"{r2['window_deg']} {r2['theta_deg']}")
    r3 = pick(rng(0, 355))
    check("every turn works: one window all round, no failure", r3["theta_deg"] is not None and len(r3["windows"]) == 1 and r3["width_deg"] == 355, f"{r3['theta_deg']} {r3['width_deg']}")


def case_middle():
    print("\n3. the middle; between two steps the later turn")
    r = pick(rng(100, 120))                        # 5 turns, odd: 100 105 110 115 120
    check("5 turns 100..120: the exact middle, 110", r["theta_deg"] == 110, f"{r['theta_deg']}")
    r = pick(rng(100, 115))                        # 4 turns, even: the middle (107.5) is between 105 and 110
    check("4 turns 100..115: the middle (107.5) falls between 105 and 110: the later one, 110", r["theta_deg"] == 110, f"{r['theta_deg']}")


def case_tie():
    print("\n4. two equally wide windows")
    r = pick(rng(200, 220) + rng(40, 60))
    check("windows 40-60 and 200-220 (same width): the one first going up from 0, 40-60: middle 50", r["theta_deg"] == 50 and r["window_deg"] == [40, 60], f"{r['theta_deg']} {r['window_deg']}")
    r = pick([355, 0, 5] + rng(100, 110))
    check("a window across 0 (355, 0, 5) against 100-110 (same width): the wrapped one counts as the one at 0 and wins: middle 0", r["theta_deg"] == 0 and r["window_deg"] == [-5, 5], f"{r['theta_deg']} {r['window_deg']}")


def case_narrow():
    print("\n5. a window under 10 degrees fails")
    r = pick([100])
    check("one working turn (width 0): no angle, reason names the minimum", r["theta_deg"] is None and "no place angle window" in r["reason"] and "under the 10" in r["reason"], r["reason"])
    r = pick(rng(100, 105) + rng(200, 205))
    check("windows of 5 degrees (two turns): fails", r["theta_deg"] is None and r["width_deg"] == 5, f"{r['width_deg']}")
    r = pick(rng(100, 110))
    check("exactly 10 degrees: passes (the minimum is 'at least')", r["theta_deg"] == 105, f"{r['theta_deg']}")
    r = pick([])
    check("no working turn at all: no angle, 'no place angle window'", r["theta_deg"] is None and r["reason"].startswith("no place angle window"), r["reason"])


def case_nav_off():
    print("\n6. navigation off computes the angle (stance selection, scene context only)")
    import numpy as np
    from src import bench_stance as bs
    from src.mpvi_postprocess import postprocess
    from src.stance_select import make_context, select_bench_stance
    from src.task_beaker_hotplate import load_task
    from src.task_config import BENCH_STANCE_CFG, TASK_CFG
    from src.world_model import StaticTaskSource, WorldModel
    import experiments.stance_select_test as sst

    class SearchOnly:
        """No full check: only the angle search, which picks from the turns written here (355, 0, 5 and 10: four turns, the later middle, 5)."""
        calls = []

        def place_theta_at(self, stance, points):
            SearchOnly.calls.append(tuple(stance))
            return choose_place_window([355, 0, 5, 10], STEP, NEED) | {"failed_stop": {}}

    sim = load_task()
    maps = bs.load_maps("data/reach_map", sides=("left",))
    ctx = make_context(sim.model, sim.data, maps)
    tagged = postprocess(sst.PLAN4, False, say=lambda *_: None)
    w = WorldModel([StaticTaskSource()])
    w.refresh(0.0)
    cfg_off = {**copy.deepcopy(BENCH_STANCE_CFG), "navigation": False}
    sel = select_bench_stance(tagged, w, TASK_CFG, ctx, cfg_off, full_check=SearchOnly(), say=lambda *_: None)
    th = [g.get("place_theta_deg") for g in sel["plan"]["segments"] if g.get("primitive") == "place"]
    check("the place step gets a computed angle (5 degrees: later middle of 355, 0, 5, 10), not 0 and not missing", sel["ok"] and th == [5.0], f"{th} {sel['stop']}")
    check("the search ran once, at TASK_CFG's own stance (xy and pedestal)", len(SearchOnly.calls) == 1 and SearchOnly.calls[0][:2] == tuple(TASK_CFG["staging_xy"]) and abs(SearchOnly.calls[0][3] - TASK_CFG["pedestal_q"]) < 1e-9, f"{SearchOnly.calls}")


if __name__ == "__main__":
    case_widest()
    case_wrap()
    case_middle()
    case_tie()
    case_narrow()
    case_nav_off()
    print(f"\n{sum(results)}/{len(results)} passed")
    sys.exit(0 if all(results) else 1)
